(s) => {
  const T = {"is_certificate":{"want":"yes","pass":0.8,"fail":0.2,"label":"not a certificate of incorporation"},"looks_altered":{"want":"no","pass":0.6,"fail":0.8,"label":"looks altered"},"seal_present":{"want":"yes","pass":0.7,"fail":0.25,"label":"no seal or certification stamp"},"signature_present":{"want":"yes","pass":0.7,"fail":0.25,"label":"a signature is missing"},"name_consistent":{"want":"yes","pass":0.7,"fail":0.3,"label":"the company name differs between places"},"date_not_future":{"want":"yes","pass":0.7,"fail":0.3,"label":"a date is in the future"}};
  const raw = (s["checks$answers"] || {}).answers || {};
  const p = {}; const failed = []; const unsure = [];
  for (const q of Object.keys(T)) {
    const t = T[q];
    const v = raw[q] && typeof raw[q].noul === "number" ? raw[q].noul : null;
    p[q] = v;
    if (v === null) { unsure.push(q + ": no probability came back"); continue; }
    const good = t.want === "yes" ? v >= t.pass : v < t.pass;
    const bad = t.want === "yes" ? v < t.fail : v >= t.fail;
    if (bad) failed.push(t.label + " (" + q + " " + v.toFixed(2) + ")");
    else if (!good) unsure.push(q + " is unclear (P(yes) " + v.toFixed(2) + ")");
  }

  return { action: failed.length ? "fail" : unsure.length ? "borderline" : "pass", failed, unsure, unsure_text: unsure.join("; "), p };
}
